function policyVerify(){const p=policy(),errors=[];if(p.schema_version!=='1.0'||p.phase!=='ADVANCED_EXECUTION_P2_ISOLATED_WORKERS')errors.push('PHASE_OR_SCHEMA_INVALID');for(const n of ['heartbeat_interval_ms','heartbeat_timeout_ms','start_timeout_ms','stop_timeout_ms','max_recovery_count','max_start_count','max_read_scopes','max_write_scopes','max_scope_length'])if(!Number.isInteger(p[n])||p[n]<1)errors.push(`NUMERIC_POLICY_INVALID:${n}`);if(!p.worker_id_prefix||!Array.isArray(p.roles?.read_only)||!Array.isArray(p.roles?.product_writer)||!Array.isArray(p.always_protected_paths)||!Array.isArray(p.environment_allowlist))errors.push('POLICY_SHAPE_INVALID');const r=p.rules||{};for(const k of ['require_p1_worktree_receipt','require_live_p1_worktree','require_task_contract','require_task_id_match','require_clean_worktree_at_provision','derive_worker_id','canonical_state_paths','one_worker_per_worktree','one_worktree_per_worker','read_scope_default_all','write_scope_must_be_task_in_scope','read_only_role_write_forbidden','product_writer_requires_write_scope','worker_supervisor_process_enabled','handoff_required_for_completion','handoff_owned_by_worker','evidence_owned_by_worker','recovery_enabled','worktree_cleanup_owned_by_p1','project_protected_paths_enforced','control_plane_mutations_serialized','evidence_snapshotted_before_cleanup'])if(r[k]!==true)errors.push(`RULE_MISSING:${k}`);for(const k of ['allow_global_write_scope','cross_worktree_access_allowed','external_path_access_allowed','symlink_escape_allowed','arbitrary_shell_allowed','network_used','concurrency_enabled','dispatcher_enabled','queue_enabled','multi_machine_enabled'])if(r[k]!==false)errors.push(`RULE_INVALID:${k}`);if(r.max_active_workers!==1)errors.push('MAX_ACTIVE_WORKERS_MUST_BE_ONE');if(r.target_agent_runtime_binding!=='DEFERRED_MASTER_VALIDATION')errors.push('TARGET_RUNTIME_BOUNDARY_INVALID');return{status:errors.length?'WORKER_POLICY_INVALID':'WORKER_POLICY_VALID',valid:!errors.length,errors,policy:p}}
function certificatePaths(){return['advanced-execution/workers/worker-manager.mjs','advanced-execution/workers/worker-runtime.mjs','advanced-execution/policies/worker-policy.json','advanced-execution/schemas/worker-assignment.schema.json','advanced-execution/schemas/worker-session.schema.json','advanced-execution/schemas/worker-handoff.schema.json','advanced-execution/schemas/worker-handoff-input.schema.json','advanced-execution/templates/worker-assignment.example.json','advanced-execution/templates/worker-handoff-input.example.json','advanced-execution/contracts/ISOLATED_WORKER.md','advanced-execution/worktrees/worktree-manager.mjs','advanced-execution/policies/worktree-policy.json','release/certifications/advanced-execution-p1.json','core/schemas/task-contract.schema.json','scripts/05-install-into-project.ps1']}
function certifyRun(outFile){if(!sourcePackageRoot)die('ADVANCED_EXECUTION_P2_CERTIFICATION_SOURCE_LAYOUT_REQUIRED',4);const pv=policyVerify(),p1Cert=path.join(sourcePackageRoot,'release/certifications/advanced-execution-p1.json'),p1=runJson(worktreeManager,['certify','verify','--certificate',p1Cert],sourcePackageRoot),inputs=certificatePaths().map(rel=>({path:rel,sha256:hashFile(path.join(sourcePackageRoot,rel))}));const ok=pv.valid&&p1.ok;const c={schema_version:'1.0',phase:'ADVANCED_EXECUTION_P2_ISOLATED_WORKERS',status:ok?'ADVANCED_EXECUTION_P2_PACKAGE_CERTIFIED':'ADVANCED_EXECUTION_P2_PACKAGE_CERTIFICATION_FAILED',package_only:true,target_runtime_validation:'DEFERRED',claims:{p1_worktree_binding:true,derived_worker_identity:true,one_worker_one_worktree:true,real_worker_supervisor_process:true,target_agent_runtime_binding:false,path_scope_guard:true,cross_worktree_access_blocked:true,worker_owned_handoff_evidence:true,evidence_snapshotted_before_cleanup:true,project_protected_paths_enforced:true,control_plane_mutations_serialized:true,bounded_recovery:true,concurrency_disabled:true,dispatcher_queue_disabled:true,multi_machine_disabled:true,network_disabled:true,p1_cleanup_ownership_preserved:true},dependencies:{advanced_execution_p1_certificate_valid:p1.ok},inputs,created_at:now(),evidence_sha256:''};c.evidence_sha256=hashObj(c,'evidence_sha256');if(outFile)atomicWrite(path.resolve(outFile),c);return c}
function certifyVerify(file){if(!sourcePackageRoot)return{status:'ADVANCED_EXECUTION_P2_CERTIFICATE_INVALID',valid:false,errors:['SOURCE_LAYOUT_REQUIRED']};if(!file||!fs.existsSync(file))return{status:'ADVANCED_EXECUTION_P2_CERTIFICATE_INVALID',valid:false,errors:['CERTIFICATE_MISSING']};let c;try{c=read(file)}catch{return{status:'ADVANCED_EXECUTION_P2_CERTIFICATE_INVALID',valid:false,errors:['CERTIFICATE_UNREADABLE']}};const errors=[];if(c.phase!=='ADVANCED_EXECUTION_P2_ISOLATED_WORKERS')errors.push('PHASE_INVALID');if(c.package_only!==true||c.target_runtime_validation!=='DEFERRED')errors.push('RUNTIME_BOUNDARY_INVALID');if(c.evidence_sha256!==hashObj(c,'evidence_sha256'))errors.push('CERTIFICATE_INTEGRITY_MISMATCH');const expected=certificatePaths(),current=new Map(expected.map(rel=>[rel,hashFile(path.join(sourcePackageRoot,rel))]));for(const x of c.inputs||[])if(current.get(x.path)!==x.sha256)errors.push(`INPUT_DRIFT:${x.path}`);if((c.inputs||[]).length!==expected.length)errors.push('INPUT_SET_DRIFT');const p1=runJson(worktreeManager,['certify','verify','--certificate',path.join(sourcePackageRoot,'release/certifications/advanced-execution-p1.json')],sourcePackageRoot);if(!p1.ok)errors.push('P1_CERTIFICATE_INVALID');return{status:errors.length?'ADVANCED_EXECUTION_P2_CERTIFICATE_STALE_OR_TAMPERED':'ADVANCED_EXECUTION_P2_CERTIFICATE_VALID',valid:!errors.length,errors,certificate:c}}

