if(group==='worker'&&cmd==='stop'){const repo=path.resolve(take('--repo',''));const r=withControlLock(repo,()=>stopWorker(repo,path.resolve(take('--session',''))));out(r);process.exit(0)}
if(group==='worker'&&cmd==='recover'){const repo=path.resolve(take('--repo',''));const r=withControlLock(repo,()=>recoverWorker(repo,path.resolve(take('--session',''))));out(r);process.exit(0)}
if(group==='worker'&&cmd==='finalize'){const repo=path.resolve(take('--repo',''));const r=withControlLock(repo,()=>finalizeWorker(repo,path.resolve(take('--session','')),path.resolve(take('--handoff',''))));out(r);process.exit(0)}
