if(group==='handoff'&&cmd==='seal'){const repo=path.resolve(take('--repo',''));const r=withControlLock(repo,()=>sealHandoff(repo,path.resolve(take('--session','')),path.resolve(take('--input',''))));out(r);process.exit(0)}
